// Typed access to src/data/fixtures.json (generated by scripts/gen-fixtures.mjs from the shared design fixtures).
// Build-time only: nothing here is shipped to the browser unless a page serialises it on purpose.
import raw from '../data/fixtures.json';
import type { Row, XY } from './geo';

/* eslint-disable @typescript-eslint/no-explicit-any */
export interface Trip {
  id: string; rows: Row[]; vehicleId?: string; durationS?: number; glyph?: XY[];
  cleanest?: { t0: number; t1: number; text: string; [k: string]: any };
  smoothness?: any; tip?: any; story?: any; gg?: { points: XY[]; envelope: { radiiG: number[] } }; events?: any[];
}
export const DATA = raw as unknown as {
  trips: Record<string, Trip>;
  vehicles: { id: string; nickname: string; colour: string }[];
  recap: any; routeCommute: any; prices: Record<'US' | 'CA', { monthly: string; annual: string; founding: string; annualPerMonth: string }>;
};

export const trip = (id: string): Trip => {
  const t = DATA.trips[id];
  if (!t) throw new Error(`fixture trip ${id} not exported: add it to scripts/gen-fixtures.mjs`);
  return t;
};
export const vehicle = (id: string) => DATA.vehicles.find((v) => v.id === id)!;

export const HERO_TRIP_ID = 't20261105-0742';   // Thursday morning, The Commute: new route record 91 (beats 89 from 14 Oct)
export const NEEDED_TRIP_ID = 't20261020-0740'; // needed brake at Spadina & King
export const ROAD_TRIP_IDS = ['t20261105-1745', 't20261101-1020', 't20261024-0930', 't20261013-1742', 't20261017-1120', 't20261104-0650'];

/** "5 Nov" (day-month, as in all DrivePerf copy). */
export const fmtDate = (iso: string, opts: Intl.DateTimeFormatOptions = { day: 'numeric', month: 'short' }) =>
  new Date(iso.length === 10 ? iso + 'T12:00:00' : iso).toLocaleDateString('en-GB', { timeZone: 'America/Toronto', ...opts });
